mapper.sql:
WHERE delete_flag = 0
AND corp_id = #{corpId}
AND brand = #{brand}
AND category = #{category}
AND model LIKE CONCAT('%', #{model}, '%')
AND status = #{status}

mapper.select:
SELECT 
FROM ops_product_price
WHERE delete_flag = 0 AND status = 1 AND corp_id = #{corpId}
  AND brand = #{brand} AND model = #{model}
AND category = #{category}
